const cras = './idosos.html#localizador';
const inss = 'https://www.gov.br/inss/pt-br/canais_atendimento/meu-inss/meu-inss';
const bpc = 'https://www.gov.br/mds/pt-br/acoes-e-programas/suas/beneficios-assistenciais/beneficio-assistencial-ao-idoso-e-a-pessoa-com-deficiencia-bpc';
export function buildSupportPlan(a) {
  const steps = [];
  const add = (id, title, reason, action, question, url, source) => steps.push({ id, title, reason, action, question, url, source });
  if (a.mobility === 'hard') add('home', 'Pergunte sobre avaliação para cuidado domiciliar', 'Você indicou dificuldade para sair de casa.', 'Entre em contato com a UBS responsável pelo endereço. A equipe avalia o cuidado indicado e as possibilidades de atendimento.', 'Como solicitar avaliação para uma pessoa com dificuldade de deslocamento?', cras, 'https://saude.sorocaba.sp.gov.br/destaques/unidades-basicas-de-saude/');
  else if (a.care === 'yes') add('health', 'Organize o acompanhamento na UBS', 'Você indicou necessidade de acesso a cuidados de saúde.', 'Confirme qual UBS atende o endereço e como acessar consulta, vacinação ou acompanhamento.', 'Como agendar o atendimento de que preciso e quais documentos levar?', cras, 'https://saude.sorocaba.sp.gov.br/destaques/unidades-basicas-de-saude/');
  if (a.income === 'hard') add('income', 'Procure orientação no CRAS', 'Você indicou dificuldade para pagar despesas básicas.', 'Peça avaliação da situação familiar e orientação sobre os apoios disponíveis. O atendimento não significa concessão automática de auxílio.', 'Quais serviços ou apoios podem ser avaliados para minha situação?', cras, 'https://cidadania.sorocaba.sp.gov.br/destaques/cras/');
  if (a.cad === 'update' || (a.income === 'hard' && a.cad !== 'yes')) add('cad', 'Confira o Cadastro Único', a.cad === 'update' ? 'Você indicou necessidade de atualização ou mudanças na família.' : 'Você indicou dificuldade com a renda e não confirmou um cadastro atualizado.', 'Procure orientação sobre inscrição ou atualização. A entrevista não verificou a renda nem os critérios de cadastro.', 'Minha família pode se cadastrar? O cadastro precisa ser atualizado? Quais documentos devo apresentar?', cras, 'https://www.gov.br/mds/pt-br/acoes-e-programas/cadastro-unico/Cadastro-unico/');
  if (a.income === 'hard' && !['bpc', 'pension'].includes(a.benefit) && (a.age === '65+' || a.disability === 'yes')) add('bpc', 'Peça orientação para avaliar o BPC', a.age === '65+' ? 'Você informou 65 anos ou mais e dificuldade com a renda.' : 'Você informou impedimento de longo prazo ou deficiência e dificuldade com a renda.', 'O BPC tem critérios de baixa renda e outros requisitos. Para a pessoa idosa, a idade é a partir de 65 anos; para pessoa com deficiência, há avaliação específica. Não calculamos renda familiar nem confirmamos elegibilidade.', 'Quais critérios preciso verificar e quais documentos faltam para avaliar um pedido de BPC?', cras, bpc);
  if (a.benefit === 'pending') add('pending', 'Acompanhe o pedido ou a dificuldade com o benefício', 'Você informou um pedido em análise ou problema com benefício.', 'Consulte o Meu INSS ou ligue 135. Tenha o protocolo, se houver, e confira as orientações oficiais.', 'Há alguma pendência? Qual é o próximo passo e como acompanho a resposta?', 'https://meu.inss.gov.br/', inss);
  else if (a.benefit === 'none' && a.age !== 'unknown' && !steps.some(x => x.id === 'bpc')) add('inss', 'Esclareça sua situação previdenciária', 'Você informou não receber aposentadoria, pensão ou BPC.', 'Se houver dúvidas sobre contribuições ou pedidos, consulte o INSS. Idade, sozinha, não garante aposentadoria; esta entrevista não apurou histórico de contribuição.', 'Como consulto minhas contribuições e os requisitos aplicáveis ao meu caso?', 'https://meu.inss.gov.br/', inss);
  if (a.support === 'little') add('support', 'Busque apoio para quem cuida e para quem recebe cuidado', 'Você indicou falta de apoio ou sobrecarga no dia a dia.', 'Converse com o CRAS sobre a rede de apoio e, se houver necessidade de saúde, com a UBS. Combine os passos com a pessoa idosa.', 'Quais serviços de apoio e convivência existem e como acessar?', cras, 'https://cidadania.sorocaba.sp.gov.br/destaques/cras/');
  if (!steps.length) add('review', 'Escolha uma dúvida para esclarecer', 'As respostas não apontaram uma necessidade específica, ou você preferiu não informar.', 'Isso não significa ausência de direitos ou de necessidades. Você pode rever as respostas ou consultar os serviços locais quando precisar.', 'Que dificuldade eu gostaria de resolver primeiro?', cras, 'https://cidadania.sorocaba.sp.gov.br/destaques/cras/');
  return steps;
}
